statement
  : statement eol
  | title text                                                  { yy.setDiagramTitle($text.text.trim()); }
  | X_AXIS parseXAxis
  | Y_AXIS parseYAxis
  | LINE plotData                                               { yy.setLineData({text: '', type: 'text'}, $plotData); }
  | LINE text plotData                                          { yy.setLineData($text, $plotData); }
